// Public institutional information checked at tokenhub.com.br on 2026-10-21.
export const official={name:'Token Hub Tokenização Ltda.',cnpj:'28.850.452/0001-81',address:'Avenida Cassiano Ricardo, 601, sala 163 · Aquarius',city:'São José dos Campos – SP',postalCode:'12.246-870'};
export function companyIdentity(){return `<div class="company-identity"><strong>${official.name}</strong><span>CNPJ: ${official.cnpj}</span><address>${official.address}<br>${official.city} · CEP ${official.postalCode}</address></div>`;}
export function officialServices(icon){return `<section class="section official-services"><div class="container"><div class="section-head"><div><span class="eyebrow">Ecossistema TokenHub</span><h2>Aprender, planejar<br>e acompanhar.</h2></div><p>Conheça as frentes apresentadas pela TokenHub e explore os recursos desta experiência.</p></div><div class="grid3">${[['chart','Token Adviser','Carteiras recomendadas e rebalanceamento fazem parte da proposta do Adviser.','Conhecer o Adviser','#/ecossistema/adviser'],['doc','Token Academy','Conhecimento sobre tokenização, blockchain e investimentos.','Explorar conteúdos','#/conteudos'],['globe','Token App','Uma experiência digital para acompanhar a sua jornada.','Conhecer o Token App','#/ecossistema/app']].map(([i,t,p,c,h])=>`<article class="panel official-service">${icon(i)}<h3>${t}</h3><p>${p}</p><a class="arrow-link" href="${h}">${c}${icon('arrow')}</a></article>`).join('')}</div><p class="footnote">Nesta versão, os conteúdos são introdutórios e a plataforma usa dados fictícios. Recomendação personalizada, rebalanceamento e aplicativo de produção não estão conectados.</p></div></section>`;}
export function serviceContent(kind,icon){if(!['adviser','app'].includes(kind))return null;const adviser=kind==='adviser';return `<section class="section"><div class="container trust-grid"><div><span class="eyebrow">Ecossistema TokenHub</span><h1>Token ${adviser?'Adviser':'App'}</h1><p class="lead">${adviser?'Conheça a proposta de carteiras recomendadas e rebalanceamento.':'Acompanhe ativos e movimentações em uma experiência pensada para simplificar sua jornada.'}</p><div class="notice mt32">${icon('info')}<div><strong>${adviser?'Apresentação do serviço':'Experiência demonstrativa'}</strong><p>${adviser?'Esta página não recomenda uma carteira nem executa rebalanceamento. As oportunidades disponíveis aqui são cenários fictícios.':'Você pode explorar a interface web com dados fictícios. Não há aplicativo de produção ou link de instalação verificado nesta versão.'}</p></div></div><div class="row wrap mt32"><a class="btn btn-dark" href="${adviser?'#/app/oportunidades':'#/app'}">${adviser?'Explorar ativos demonstrativos':'Explorar a plataforma'}${icon('arrow')}</a><a class="btn btn-outline" href="#/contato">Falar com a equipe</a></div></div><div class="panel"><h2>${adviser?'Informação para planejar.':'Sua carteira, com contexto.'}</h2><p class="lead">${adviser?'Objetivos, prazo e tolerância a risco ajudam a organizar a análise de uma carteira. Antes de decidir, conheça as condições e os documentos de cada ativo.':'Consulte o saldo, explore o detalhamento por ativo e acompanhe as movimentações da demonstração.'}</p><a class="arrow-link mt20" href="${adviser?'#/conteudos':'#/app/carteira'}">${adviser?'Aprender na Token Academy':'Conhecer a carteira'}${icon('arrow')}</a></div></div></section>`;}
export function officialOnboarding(){return `<section class="section wash"><div class="container"><div class="section-head"><div><span class="eyebrow">Comece pela sua conta</span><h2>Do cadastro à descoberta.</h2></div><p>A jornada começa com cadastro e ativação por token. Aqui você pode conhecer as telas sem criar uma conta real.</p></div><div class="grid4">${[['Abra sua conta','Acesse o início do cadastro.'],['Preencha seus dados','Conheça as informações da jornada.'],['Ative seu acesso','Na operação oficial, a etapa prevê confirmação por token.'],['Explore e acompanhe','Conheça os ativos e sua carteira.']].map(([title,copy],i)=>`<div class="step-card"><span class="step-number">0${i+1}</span><h3>${title}</h3><p>${copy}</p></div>`).join('')}</div><a class="arrow-link mt32" href="#/cadastro">Conhecer o cadastro →</a></div></section>`;}
